--
-- TOC entry 308 (class 1259 OID 106892)
-- Name: vw_lam_versions_complete; Type: VIEW; Schema: tracer_oltp; Owner: postgres
--

CREATE VIEW tracer_oltp.vw_lam_versions_complete AS
 SELECT lv.lam_version_id,
    lv.year,
    lv.year_end,
    lv.version_name,
    lv.is_active,
    l.id AS lam_id,
    l.name AS lam_name,
    l.code AS lam_code,
    COALESCE(json_agg(DISTINCT jsonb_build_object('id', p.id, 'name', p.name, 'code', p.code, 'degree', p.degree)) FILTER (WHERE (p.id IS NOT NULL)), '[]'::json) AS programs,
    COALESCE(json_agg(DISTINCT jsonb_build_object('threshold_id', t.id, 'indicator_id', ti.id, 'indicator_key', ti.key, 'indicator_name', ti.name, 'unit', ti.unit, 'operator', ti.operator, 'level', t.level, 'value', t.value)) FILTER (WHERE (t.id IS NOT NULL)), '[]'::json) AS thresholds
   FROM (((((( SELECT lam_versions.id AS lam_version_id,
            lam_versions.lam_id,
            lam_versions.year,
            lam_versions.version_name,
            lam_versions.is_active,
            (lead(lam_versions.year) OVER (PARTITION BY lam_versions.lam_id ORDER BY lam_versions.year) - 1) AS year_end
           FROM tracer_oltp.lam_versions) lv
     JOIN tracer_oltp.lams l ON ((l.id = lv.lam_id)))
     LEFT JOIN tracer_oltp.lam_programs lp ON ((lp.lam_id = l.id)))
     LEFT JOIN tracer_oltp.programs p ON ((p.id = lp.program_id)))
     LEFT JOIN tracer_oltp.thresholds t ON ((t.lam_version_id = lv.lam_version_id)))
     LEFT JOIN tracer_oltp.threshold_indicators ti ON ((ti.id = t.indicator_id)))
  GROUP BY lv.lam_version_id, lv.year, lv.year_end, lv.version_name, lv.is_active, l.id, l.name, l.code;


ALTER VIEW tracer_oltp.vw_lam_versions_complete OWNER TO postgres;

