    l.code AS lam_code
   FROM ((((tracer_oltp.thresholds t
     JOIN tracer_oltp.threshold_indicators ti ON ((ti.id = t.indicator_id)))
     JOIN ( SELECT lam_versions.id,
            lam_versions.lam_id,
            lam_versions.year,
            lam_versions.version_name,
            lam_versions.is_active,
            lam_versions.created_at,
            lam_versions.updated_at,
            (lead(lam_versions.year) OVER (PARTITION BY lam_versions.lam_id ORDER BY lam_versions.year) - 1) AS year_end
           FROM tracer_oltp.lam_versions) lv ON ((lv.id = t.lam_version_id)))
     JOIN tracer_oltp.lams l ON ((l.id = lv.lam_id)))
     LEFT JOIN tracer_oltp.threshold_configs tc ON (((tc.lam_version_id = t.lam_version_id) AND (tc.indicator_id = t.indicator_id))));


ALTER VIEW tracer_oltp.vw_thresholds_complete OWNER TO postgres;

--
-- TOC entry 302 (class 1259 OID 99339)
-- Name: vw_users_with_programs; Type: VIEW; Schema: tracer_oltp; Owner: postgres
--

CREATE VIEW tracer_oltp.vw_users_with_programs AS
 SELECT u.id,
    u.name,
    u.email,
    u.role,
    u.program_id,
    p.name AS program_name,
    p.code AS program_code,
    p.degree AS program_degree,
    u.created_at,
    u.updated_at
   FROM (tracer_oltp.users u
     LEFT JOIN tracer_oltp.programs p ON ((u.program_id = p.id)));


ALTER VIEW tracer_oltp.vw_users_with_programs OWNER TO postgres;

